    },
    execute: (arguments, cancelToken, onUpdate) async {
      try {
        final seconds = (arguments['seconds'] as num?)?.toInt().clamp(1, 30);
        final file = await gateway.generateVideo(
          prompt: (arguments['prompt'] ?? '').toString(),
          seconds: seconds?.toInt(),
