      }
    },
  );
}

/// Renders a caught error as LLM-facing text (StateError messages are the
/// actionable ones; anything else is stringified).
String _errorText(Object error) =>
    'Error: ${error is StateError ? error.message : error}';

/// MiniMax video size string → the (resolution, aspect-ratio) request
/// pair; null when [size] is not a usable `WxH` pair (the caller falls
/// back to the provider default `2K`, `16:9`).
@visibleForTesting
(String, String)? minimaxVideoSizeRequest(String? size) {
  final dims = minimaxVideoDims(size);
  if (dims == null) return null;
  final g = _minimaxGcd(dims.$1, dims.$2);
  return (
    dims.$1 >= 1920 ? '2K' : '1080P',
    '${dims.$1 ~/ g}:${dims.$2 ~/ g}',
  );
}

/// Parses a `WIDTHxHEIGHT` string (case-insensitive) into positive
/// dimensions; null when [size] is missing, not exactly `WxH`, or not
/// two positive integers.
@visibleForTesting
(int, int)? minimaxVideoDims(String? size) {
  if (size == null || size.trim().isEmpty) return null;
  final parts = size.toLowerCase().split('x');
  if (parts.length != 2) return null;
  final w = int.tryParse(parts[0]);
  final h = int.tryParse(parts[1]);
  if (!_minimaxDimsValid(w, h)) return null;
  return (w!, h!);
}

bool _minimaxDimsValid(int? w, int? h) =>
    w != null && h != null && w > 0 && h > 0;

int _minimaxGcd(int a, int b) {
  var x = a;
  var y = b;
  while (y != 0) {
    final t = x % y;
    x = y;
    y = t;
  }
  return x;
}

/// The `models:` section of `~/.fah/config.yaml`: per-slot media model
/// overrides (the CLI half of the app's media-models feature) plus named
/// custom model definitions `/model <name>` can switch to.
///
/// ```yaml
/// models:
///   slots:                        # media slot overrides (app slot schema)
///     vision:
///       providerKind: openai-completions
///       baseUrl: https://api.openai.com/v1
///       modelId: gpt-4o
///       apiKeyName: OPENAI_API_KEY  # optional; key NAME, never the value
///   custom:                       # named model definitions (/model <name>)
///     fast:
///       provider: openai            # catalog provider name
///       baseUrl: https://api.openai.com/v1
///       model: gpt-4o-mini
///       contextWindow: 128000       # optional (catalog default otherwise)
///       maxTokens: 4096             # optional
///       input: [text, image]        # optional
///       authHeader: x-api-key       # optional; sends `x-api-key: <key>`
///                                   # instead of `Authorization: Bearer`
///       streamIdleTimeoutMs: 240000 # optional; per-provider watchdog
///       connectTimeoutMs: 45000     #   tuning (issue #1398) — entry >
///                                   #   `providerTimeouts:` > defaults
/// ```
///
/// Stall-recovery tuning recipe (issue #1398): set `streamIdleTimeoutMs ≈
/// 2× p95` of the model's measured inter-chunk gap (the tuning report
/// prints the per-model p50/p95). Defaults stay conservative (300 s) —
/// healthy reasoning gaps of ~200 s are on record; tuning is opt-in per
/// entry.
///
/// Parsed strictly like `roles:`/`ttsr:`: any schema error throws
/// [ConfigException] at startup instead of silently dropping the section.
library;

import 'dart:convert';

import 'package:yaml/yaml.dart';

import '../exceptions.dart';
import '../providers/provider_tuning.dart' show parseProviderTimeoutMs;
import 'capability_resolver.dart';
import 'media_model_slots.dart';
import 'provider_catalog.dart';

/// A named custom model definition (`models.custom.<name>`): a concrete
/// provider/endpoint/model triple with optional token-limit and modality
/// overrides, switchable at runtime with `/model <name>`.
final class CustomModelDefinition {
  /// Creates a custom model definition.
  const CustomModelDefinition({
    required this.provider,
    required this.baseUrl,
    required this.model,
    this.contextWindow,
    this.maxTokens,
    this.input,
    this.authHeader,
    this.connectTimeout,
    this.streamIdleTimeout,
  });

  /// Parses one definition from yaml, strictly: [name] is the map key;
  /// `provider` must be a catalog provider name (see [providerCatalog]),
  /// `baseUrl`/`model` non-empty strings, `contextWindow`/`maxTokens`
  /// positive integers, `input` a non-empty list of `text`/`image`.
  factory CustomModelDefinition.fromYaml(String name, Object? node) {
    final where = 'models.custom.$name';
    if (node is! YamlMap) {
      throw ConfigException(
        '$where must be a map with provider, baseUrl, model',
      );
    }
    const knownFields = [
      'provider',
      'baseUrl',
      'model',
      'contextWindow',
      'maxTokens',
      'input',
      'authHeader',
      'connectTimeoutMs',
      'streamIdleTimeoutMs',
    ];
    for (final key in node.keys) {
      if (!knownFields.contains(key)) {
        throw ConfigException(
          'unknown field "$key" in $where — expected '
          '${knownFields.join(', ')}',
        );
      }
    }
    String required(String field) {
      final value = node[field];
      if (value is! String || value.trim().isEmpty) {
        throw ConfigException('$where.$field must be a non-empty string');
      }
      return value.trim();
    }

    final provider = required('provider');
    // Load-time validation mirrors the switch-time resolution exactly
    // (both identifiers, FA_PROVIDERS filter) — a kind-shaped or
    // filtered-out entry fails HERE with the enabled list, never later
    // at `/model` (issue #772 review).
    final spec = resolveCliProviderSpec(provider, honorBuildFilter: true);
    if (spec == null) {
      throw ConfigException(
        'unknown provider "$provider" in $where — supported providers: '
        '${enabledProviderNames().join(', ')}',
      );
    }
    final authHeader = parseAuthHeaderName(node['authHeader'], where);
    validateAuthHeaderDialect(authHeader, spec, where);
    int? optionalInt(String field) {
      final value = node[field];
      if (value == null) return null;
      if (value is! int || value <= 0) {
        throw ConfigException('$where.$field must be a positive integer');
      }
      return value;
    }

    final input = switch (node['input']) {
      null => null,
      final YamlList list when list.isNotEmpty => [
        for (final entry in list)
          switch (entry) {
            'text' || 'image' => entry as String,
            _ => throw ConfigException(
              '$where.input entries must be "text" or "image", got: $entry',
            ),
          },
      ],
      final other => throw ConfigException(
        '$where.input must be a non-empty list of "text"/"image", '
        'got: $other',
      ),
    };
    return CustomModelDefinition(
      provider: provider,
      baseUrl: required('baseUrl'),
      model: required('model'),
      contextWindow: optionalInt('contextWindow'),
      maxTokens: optionalInt('maxTokens'),
      input: input,
      authHeader: authHeader,
      // Per-provider stall-recovery tuning (issue #1398): the watchdog
      // knobs ride the registry entry, same place baseUrl/keys live.
      connectTimeout: parseProviderTimeoutMs(
        node['connectTimeoutMs'],
        'connectTimeoutMs',
        where,
      ),
      streamIdleTimeout: parseProviderTimeoutMs(
        node['streamIdleTimeoutMs'],
        'streamIdleTimeoutMs',
        where,
      ),
    );
  }

  /// Catalog provider name (`openrouter`, `openai`, `anthropic`, `google`).
  final String provider;

  /// API base URL.
  final String baseUrl;

  /// Model id sent to the provider.
  final String model;

  /// Total context window in tokens (catalog default when null).
  final int? contextWindow;

  /// Maximum output tokens (catalog default when null).
  final int? maxTokens;

  /// Input modalities (`text`/`image`; catalog default when null).
  final List<String>? input;

  /// Auth header name riding the model to the wire (`authHeader:` on the
  /// entry, issue #964): `x-api-key` sends `x-api-key: <key>` instead of
  /// `Authorization: Bearer <key>`. Null keeps the Bearer default.
  final String? authHeader;

  /// Per-provider connect/first-headers watchdog override
  /// (`connectTimeoutMs`, issue #1398). Null keeps the global
  /// `providerTimeouts:` value, then the 180 s default.
  final Duration? connectTimeout;

  /// Per-provider stream-idle watchdog override (`streamIdleTimeoutMs`,
  /// issue #1398). Null keeps the global value, then the 300 s default.
  final Duration? streamIdleTimeout;

  /// Writes the definition as yaml lines at [indent] (string values are
  /// JSON-quoted — valid yaml scalars that round-trip any url/model id).
  void writeYaml(StringBuffer buffer, String indent) {
    buffer
      ..write('${indent}provider: ${jsonEncode(provider)}\n')
      ..write('${indent}baseUrl: ${jsonEncode(baseUrl)}\n')
      ..write('${indent}model: ${jsonEncode(model)}\n');
    if (contextWindow != null) {
      buffer.write('${indent}contextWindow: $contextWindow\n');
    }
    if (maxTokens != null) buffer.write('${indent}maxTokens: $maxTokens\n');
    final modalities = input;
    if (modalities != null) {
      buffer.write('${indent}input: ${jsonEncode(modalities)}\n');
    }
    final authName = authHeader;
    if (authName != null) {
      buffer.write('${indent}authHeader: ${jsonEncode(authName)}\n');
    }
    if (connectTimeout != null) {
      buffer.write(
        '${indent}connectTimeoutMs: ${connectTimeout!.inMilliseconds}\n',
      );
    }
    if (streamIdleTimeout != null) {
      buffer.write(
        '${indent}streamIdleTimeoutMs: ${streamIdleTimeout!.inMilliseconds}\n',
      );
    }
  }

  @override
