    baseUrl: 'https://api.test/v1',
    modelId: modelId,
    apiKey: '[REDACTED:Sensitive Value]',
  ),
  store: store,
  resolveKey: resolveKey,
);

String _textOf(ToolExecutionResult result) =>
    result.content.whereType<TextContent>().map((b) => b.text).join();

